function Button({children,...rest}){
    return <>
    <button {...rest}>{children}</button>
    </>
}

function FaceBookButton ({children, ...rest}){
    return <>
    <h3> Composition</h3>
    <Button {...rest}>F-{children}</Button>
    </>
}

export {
    Button,
    FaceBookButton
}
